const BarItem = ({
  value,
  label,
  color,
  iconType,
  delay,
  maxHeight,
}: {
  value: number;
  label: string;
  color: string;
  iconType: string;
  delay: number;
  maxHeight: number;
}) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  const grow = spring({
    frame: frame - delay,
    fps,
    config: { damping: 14, stiffness: 80 },
  });

  const opacity = interpolate(frame - delay, [0, 10], [0, 1], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' });
  const textY = interpolate(grow, [0, 1], [20, 0]);

  // Gradient logic: solid at bottom, slightly transparent at top to mimic the image style
  const background = `linear-gradient(0deg, ${color} 0%, ${color}EE 70%, ${color}aa 100%)`;

  return (
    <div
      style={{
        height: "100%",
        width: "20%",
        display: "flex",
        flexDirection: "column",
        justifyContent: "flex-end",
        alignItems: "center",
        position: "relative",
      }}
    >
      {/* Percentage Text */}
      <div
        style={{
          opacity: grow,
          transform: `translateY(${textY}px)`,
          fontFamily: "Oswald",
          fontWeight: 700,
          fontSize: "48px",
          color: "#1a1a1a",
          marginBottom: "10px",
          textAlign: "center",
          lineHeight: 0.9,
        }}
      >
        {Math.round(value * grow)}
        <span style={{ fontSize: "28px", verticalAlign: "top", marginLeft: "2px" }}>%</span>
      </div>

      {/* Bar */}
      <div
        style={{
          width: "100%",
          height: `${(value / 20) * maxHeight}px`, // Scaling logic
          background,
          transform: `scaleY(${grow})`,
          transformOrigin: "bottom center",
          display: "flex",
          justifyContent: "center",
          alignItems: "flex-end",
          paddingBottom: "20px",
          position: "relative",
        }}
      >
         {/* Icon */}
        <div style={{ opacity, transform: `translateY(${interpolate(grow, [0, 1], [10, 0])}px)` }}>
           <BarIcon type={iconType} color="white" />
        </div>
      </div>

      {/* Label */}
      <div
        style={{
          marginTop: "15px",
          fontFamily: "Inter",
          fontWeight: 700,
          fontSize: "24px",
          color: "#333",
          opacity,
        }}
      >
        {label}
      </div>
    </div>
  );
};

const ListItem = ({
  label,
  text,
  color,
  delay,
  labelFontSize,
  textFontSize,
}: {
  label: string;
  text: string;
  color: string;
  delay: number;
  labelFontSize: number;
  textFontSize: number;
}) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  const enter = spring({
    frame: frame - delay,
    fps,
    config: { damping: 15 },
  });

  const opacity = interpolate(frame - delay, [0, 15], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  const translateX = interpolate(enter, [0, 1], [50, 0]);

  return (
    <div
      style={{
        marginBottom: "30px",
        opacity,
        transform: `translateX(${translateX}px)`,
        display: "flex",
        flexDirection: "column",
        gap: "8px",
      }}
    >
      <div style={{ display: "flex", alignItems: "center", gap: "10px" }}>
        <div style={{ width: "12px", height: "4px", backgroundColor: color, borderRadius: "2px" }} />
        <span style={{ fontFamily: "Inter", fontWeight: 700, fontSize: `${labelFontSize}px`, color: "#1a1a1a" }}>
          {label}
        </span>
      </div>
      <p
        style={{
          fontFamily: "Inter",
          fontSize: `${textFontSize}px`,
          color: "#444",
          lineHeight: 1.5,
          margin: 0,
          maxWidth: "400px",
        }}
      >
        {text}
      </p>
    </div>
  );
};

